var t=`0158-pizza-margherita`;var i=`world-0158`;var n=`IT`;var s=`southern-europe`;var o=4;var r=124;var l={en:`Pizza Margherita`,ua:`Піца Маргарита`};var u={en:`A classic dish from Italy, featuring fresh mozzarella, basil, 00 flour, instant yeast. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Італія. Основні складники: свіжа моцарела, базилік, пшеничне борошно типу 00, інстантні дріжджі. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var g=[{en:`Mix and knead into a supple yeast dough. Cover and leave in a warm place until roughly doubled, about 90 minutes.`,ua:`Змішайте й вимісіть м’яке дріжджове тісто. Накрийте та поставте в тепле місце до збільшення об’єму приблизно вдвічі, орієнтовно на 90 хвилин.`,t:[`mixing`,`kneading`,`bulk-fermentation`],m:90,i:[[`00-flour`,530,`g`],[`water`,330,`ml`],[`instant-yeast`,3,`g`],[`table-salt`,11,`g`],[`extra-virgin-olive-oil`,20,`ml`]]},{en:`Roll or press the prepared dough evenly into the desired thickness and shape.`,ua:`Розкачайте або розпластайте підготовлене тісто рівномірним шаром потрібної товщини та форми.`,t:[`pressing`,`rolling-out-dough`],m:20,i:[]},{en:`Cook the listed sauce ingredients over medium-low heat for about 4 minutes until aromatic and slightly thickened.`,ua:`Готуйте складники соусу на помірно слабкому вогні приблизно 4 хвилин до появи аромату та легкого загустіння.`,t:[`sauteing`,`reducing-sauce`],m:4,i:[[`tomato-passata`,260,`g`],[`table-salt`,3,`g`]]},{en:`Bake in a thoroughly preheated 230–250°C oven for about 10 minutes until the crust is deeply golden and the filling is cooked.`,ua:`Випікайте в добре розігрітій до 230–250°C духовці приблизно 10 хвилин до насичено-золотистої скоринки та готовності начинки.`,t:[`high-temperature-roasting`,`baking`],m:10,i:[[`fresh-mozzarella`,280,`g`],[`basil`,25,`g`]]}];var d={slug:t,id:i,country:`IT`,region:s,servings:4,minutes:124,title:l,text:u,steps:g};export{n as country,d as default,i as id,r as minutes,s as region,o as servings,t as slug,g as steps,u as text,l as title};